css.web:
.license-text {
  font-size: 0.9em;
}

a.header-link {
  font-weight: inherit !important;
  font-size: inherit !important;
  color: #000000;
  text-decoration: none;
}

a.header-link:hover::after {
  content: '#';
  padding-left: 5px;
  color: blue;
  display: inline-block;
}

/* ─── Verse layout: scripture columns + the words in the verse ───────────── */

table.twl-scripture-cols,
table.twl-verse-table {
  width: 100%;
  border-collapse: collapse;
  table-layout: fixed;
  margin: 4px 0 8px 0;
  font-size: 0.95em;
}

.twl-col-label {
  text-align: left;
  font-size: 0.72em;
  font-weight: bold;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: #555;
  border-bottom: 1px solid #ccc;
  padding: 1px 6px;
}

table.twl-scripture-cols td,
table.twl-verse-table td {
  vertical-align: top;
  padding: 3px 6px;
  border-right: 1px solid #eee;
}

table.twl-scripture-cols td:last-child,
table.twl-verse-table td:last-child {
  border-right: none;
}

table.twl-scripture-cols {
  background-color: #f9f9f9;
  border: 1px solid #ddd;
}

td.twl-scripture-text {
  font-style: italic;
}

table.twl-verse-table a {
  text-decoration: none;
}

.twl-verse-header-label {
  display: none;
}

/* OBS story frame — the text the links are about, standing in for scripture. */
.twl-frame-text {
  background-color: #f9f9f9;
  border: 1px solid #ddd;
  border-radius: 3px;
  padding: 8px 12px;
  margin: 4px 0 8px 0;
}

.twl-frame-text p {
  margin: 0;
}

.twl-frame-image {
  display: block;
  margin: 0 auto 8px auto;
  max-width: 100%;
}

/* ─── Glossary layout: one entry per article ───────────────────────────── */

.twl-category-header {
  margin-top: 1.2em;
}

article.twl-term {
  margin: 0 0 1em 0;
}

.twl-term-header {
  margin: 0.6em 0 0.2em 0;
}

.twl-term-body h1,
.twl-term-body h2 {
  font-size: 1em;
  margin: 0.5em 0 0.2em 0;
}

.twl-term-refs {
  font-size: 0.9em;
  margin: 0.3em 0 0 0;
}

.twl-term-refs .twl-ref-label {
  font-weight: bold;
}

.twl-term-refs .twl-ref-quote {
  color: #555;
}

.header-title {
  display: block;
  margin-bottom: 0.5rem;
  color: #666;
  font-size: 0.85em;
}

.cover-page {
  text-align: center;
  padding-top: 2rem;
}

.cover-page .header-title {
  display: none;
}

.cover-page .title-logo {
  display: block;
  margin: 0 auto 1rem auto;
  width: 180px;
  max-width: 60%;
  height: auto;
}

.cover-page .cover-header,
.cover-page .cover-version,
.cover-page .cover-book-title,
.cover-page .cover-resource-title {
  text-align: center;
  margin-left: auto;
  margin-right: auto;
}

.cover-page .cover-version {
  color: #666;
  font-weight: normal;
}

.running-title, .running-ref { display: none; }

css.print:
.twl-book-header,
.twl-chapter-header,
.twl-verse-header,
.twl-category-header,
.twl-term-header {
  break-after: avoid !important;
}

/* Verse layout: one chapter per page, like Translation Questions — a chapter's
   words are read together, so the next chapter opens a fresh page. */
.twl-chapter-header {
  break-before: page !important;
}

/* ...but the first chapter opens under the book heading rather than stranding
   it, and a chapter's first verse opens under the chapter heading. */
.twl-book-header + .twl-chapter-header,
.twl-chapter-header + .twl-verse-block,
section > .twl-chapter-header:first-child {
  break-before: avoid !important;
}

/* A verse — its scripture and its word table — is read as one thing. */
.twl-verse-block,
table.twl-scripture-cols,
.twl-frame-text {
  break-inside: avoid;
}

/* Glossary layout: each category opens a page; an entry stays whole. */
.twl-category-header {
  break-before: page !important;
}

.twl-book-header + .twl-category-header,
section > .twl-category-header:first-child {
  break-before: avoid !important;
}

article.twl-term {
  break-inside: avoid;
  orphans: 2;
  widows: 2;
}
